    13→  const rates = {
    14→    USD: { USD: 1.0, EUR: 0.92, GBP: 0.79, JPY: 149.50, CHF: 0.88, CAD: 1.36, AUD: 1.52 },
    15→    EUR: { USD: 1.09, EUR: 1.0, GBP: 0.86, JPY: 162.50, CHF: 0.96, CAD: 1.48, AUD: 1.65 },
    16→    GBP: { USD: 1.27, EUR: 1.16, GBP: 1.0, JPY: 189.00, CHF: 1.11, CAD: 1.72, AUD: 1.92 },
    17→    JPY: { USD: 0.0067, EUR: 0.0062, GBP: 0.0053, JPY: 1.0, CHF: 0.0059, CAD: 0.0091, AUD: 0.0102 },
    18→    CHF: { USD: 1.14, EUR: 1.04, GBP: 0.90, JPY: 169.50, CHF: 1.0, CAD: 1.55, AUD: 1.73 },
    19→    CAD: { USD: 0.74, EUR: 0.68, GBP: 0.58, JPY: 110.00, CHF: 0.65, CAD: 1.0, AUD: 1.12 },
    20→    AUD: { USD: 0.66, EUR: 0.61, GBP: 0.52, JPY: 98.00, CHF: 0.58, CAD: 0.89, AUD: 1.0 }
    21→  };
    22→  
    23→  return {
    24→    base: baseCurrency,
    25→    rates: rates[baseCurrency] || rates.USD,
    26→    timestamp: new Date().toISOString()
    27→  };
    28→};
    29→
    30→const InvestmentTracker = () => {
    31→  const [baseCurrency, setBaseCurrency] = useState('USD');
    32→  const [fxRates, setFxRates] = useState(null);
    33→  const [accounts, setAccounts] = useState([
    34→    {
    35→      id: '1',
    36→      name: 'Main Brokerage',
    37→      bank: 'Vanguard',
    38→      type: 'Brokerage',
    39→      currency: 'USD'
    40→    }
    41→  ]);
    42→  
    43→  const [holdings, setHoldings] = useState([
    44→    {
    45→      id: '1',
    46→      accountId: '1',
    47→      symbol: 'AAPL',
    48→      name: 'Apple Inc.',
    49→      type: 'Stock',
    50→      quantity: 50,
    51→      purchasePrice: 150.00,
    52→      currentPrice: 180.00,
    53→      currency: 'USD',
    54→      dividendYield: 0.52,
    55→      purchaseDate: '2023-06-15'
    56→    },
    57→    {
    58→      id: '2',
    59→      accountId: '1',
    60→      symbol: 'VOO',
    61→      name: 'Vanguard S&P 500 ETF',
    62→      type: 'ETF',
    63→      quantity: 25,
    64→      purchasePrice: 380.00,
    65→      currentPrice: 420.00,
    66→      currency: 'USD',
    67→      dividendYield: 1.45,
