    71→
    72→  const [cashBalances, setCashBalances] = useState([
    73→    {
    74→      id: '1',
    75→      accountId: '1',
    76→      currency: 'EUR',
    77→      amount: 10000.00
    78→    },
    79→    {
    80→      id: '2',
    81→      accountId: '1',
    82→      currency: 'AUD',
    83→      amount: 2000.00
    84→    },
    85→    {
    86→      id: '3',
    87→      accountId: '1',
    88→      currency: 'USD',
    89→      amount: 5000.00
    90→    },
    91→    {
    92→      id: '4',
    93→      accountId: '1',
    94→      currency: 'JPY',
    95→      amount: 500000.00
    96→    }
    97→  ]);
    98→
    99→  const [showAddAccount, setShowAddAccount] = useState(false);
   100→  const [showAddHolding, setShowAddHolding] = useState(false);
