   107→
   108→  const loadFXRates = async () => {
   109→    const rates = await fetchFXRates(baseCurrency);
   110→    setFxRates(rates);
   111→  };
   112→
   113→  const convertCurrency = (amount, fromCurrency, toCurrency) => {
   114→    if (!fxRates || fromCurrency === toCurrency) return amount;
   115→    const inBase = amount / fxRates.rates[fromCurrency];
   116→    return inBase * fxRates.rates[toCurrency];
   117→  };
   118→
   119→  const calculateHoldingMetrics = (holding) => {
   120→    const totalCost = holding.quantity * holding.purchasePrice;
   121→    const currentValue = holding.quantity * holding.currentPrice;
   122→    const gainLoss = currentValue - totalCost;
   123→    const gainLossPercent = (gainLoss / totalCost) * 100;
   124→    const annualDividend = currentValue * (holding.dividendYield / 100);
   125→    
   126→    return {
   127→      totalCost,
   128→      currentValue,
   129→      gainLoss,
   130→      gainLossPercent,
   131→      annualDividend
   132→    };
   133→  };
   134→
   135→  const getCashSummary = () => {
   136→    const filteredCash = selectedAccount === 'all'
   137→      ? cashBalances
   138→      : cashBalances.filter(c => c.accountId === selectedAccount);
   139→
   140→    // Group by currency
   141→    const byCurrency = filteredCash.reduce((acc, cash) => {
   142→      acc[cash.currency] = (acc[cash.currency] || 0) + cash.amount;
   143→      return acc;
   144→    }, {});
   145→
   146→    // Calculate total in base currency
   147→    let totalInBase = 0;
   148→    Object.entries(byCurrency).forEach(([currency, amount]) => {
   149→      totalInBase += convertCurrency(amount, currency, baseCurrency);
   150→    });
   151→
   152→    return { byCurrency, totalInBase };
   153→  };
   154→
   155→  const addCashBalance = (accountId, currency, amount) => {
