   161→    if (existing) {
   162→      // Update existing balance
   163→      setCashBalances(
   164→        cashBalances.map(c =>
   165→          c.id === existing.id
   166→            ? { ...c, amount: c.amount + amount }
   167→            : c
   168→        )
   169→      );
   170→    } else {
   171→      // Add new cash balance
   172→      setCashBalances([
   173→        ...cashBalances,
   174→        {
   175→          id: Date.now().toString(),
   176→          accountId,
   177→          currency,
   178→          amount
   179→        }
   180→      ]);
   181→    }
