   198→      totalDividends += convertCurrency(metrics.annualDividend, holding.currency, baseCurrency);
   199→    });
   200→
   201→    // Add cash to total value and cost
   202→    const cashSummary = getCashSummary();
   203→    totalValue += cashSummary.totalInBase;
   204→    totalCost += cashSummary.totalInBase; // Cash cost basis equals its value
   205→
   206→    const totalGainLoss = totalValue - totalCost;
   207→    const totalGainLossPercent = totalCost > 0 ? (totalGainLoss / totalCost) * 100 : 0;
   208→
   209→    return { totalValue, totalCost, totalGainLoss, totalGainLossPercent, totalDividends };
   210→  };
   211→
   212→  const addAccount = (newAccount) => {
   213→    setAccounts([...accounts, { ...newAccount, id: Date.now().toString() }]);
   214→    setShowAddAccount(false);
   215→  };
   216→
   217→  const addHolding = (newHolding) => {
