   242→              >
   243→                {CURRENCIES.map(curr => (
   244→                  <option key={curr} value={curr}>{curr}</option>
   245→                ))}
   246→              </select>
   247→              <button
   248→                onClick={loadFXRates}
   249→                className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
   250→                title="Refresh FX Rates"
   251→              >
   252→                <RefreshCw className="w-5 h-5" />
   253→              </button>
   254→            </div>
   255→          </div>
   256→        </div>
   257→
   258→        {/* Portfolio Summary Cards */}
   259→        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
   260→          <div className="bg-white rounded-xl shadow-md p-6">
   261→            <div className="flex items-center justify-between">
   262→              <div>
   263→                <p className="text-slate-600 text-sm font-medium">Total Value</p>
   264→                <p className="text-2xl font-bold text-slate-800 mt-1">
   265→                  {baseCurrency} {summary.totalValue.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}
   266→                </p>
   267→              </div>
   268→              <DollarSign className="w-10 h-10 text-blue-600 opacity-80" />
   269→            </div>
   270→          </div>
   271→
   272→          <div className="bg-white rounded-xl shadow-md p-6">
   273→            <div className="flex items-center justify-between">
   274→              <div>
   275→                <p className="text-slate-600 text-sm font-medium">Total Cost</p>
   276→                <p className="text-2xl font-bold text-slate-800 mt-1">
   277→                  {baseCurrency} {summary.totalCost.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}
   278→                </p>
   279→              </div>
   280→              <Wallet className="w-10 h-10 text-slate-600 opacity-80" />
   281→            </div>
   282→          </div>
   283→
   284→          <div className="bg-white rounded-xl shadow-md p-6">
