   289→                  {summary.totalGainLoss >= 0 ? '+' : ''}{baseCurrency} {summary.totalGainLoss.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}
   290→                </p>
   291→                <p className={`text-sm font-medium ${summary.totalGainLoss >= 0 ? 'text-green-600' : 'text-red-600'}`}>
