   334→
   335→          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">{Object.entries(getCashSummary().byCurrency).map(([currency, amount]) => {
   336→              const valueInBase = convertCurrency(amount, currency, baseCurrency);
