import React, { useState, useEffect } from 'react';
import { PlusCircle, TrendingUp, TrendingDown, DollarSign, Wallet, BarChart3, RefreshCw } from 'lucide-react';

// Types for our data structures
const ACCOUNT_TYPES = ['Checking', 'Savings', 'Investment', 'Retirement', 'Brokerage'];
const ASSET_TYPES = ['Stock', 'ETF', 'Bond', 'Mutual Fund', 'Cash'];
const CURRENCIES = ['USD', 'EUR', 'GBP', 'JPY', 'CHF', 'CAD', 'AUD'];

// Mock FX Rate API - In production, use a real API like exchangerate-api.com or fixer.io
const fetchFXRates = async (baseCurrency = 'USD') => {
  // Simulated API call - replace with actual API
  // These rates are approximate and for demonstration
  const rates = {
    USD: { USD: 1.0, EUR: 0.92, GBP: 0.79, JPY: 149.50, CHF: 0.88, CAD: 1.36, AUD: 1.52 },
    EUR: { USD: 1.09, EUR: 1.0, GBP: 0.86, JPY: 162.50, CHF: 0.96, CAD: 1.48, AUD: 1.65 },
    GBP: { USD: 1.27, EUR: 1.16, GBP: 1.0, JPY: 189.00, CHF: 1.11, CAD: 1.72, AUD: 1.92 },
    JPY: { USD: 0.0067, EUR: 0.0062, GBP: 0.0053, JPY: 1.0, CHF: 0.0059, CAD: 0.0091, AUD: 0.0102 },
    CHF: { USD: 1.14, EUR: 1.04, GBP: 0.90, JPY: 169.50, CHF: 1.0, CAD: 1.55, AUD: 1.73 },
    CAD: { USD: 0.74, EUR: 0.68, GBP: 0.58, JPY: 110.00, CHF: 0.65, CAD: 1.0, AUD: 1.12 },
    AUD: { USD: 0.66, EUR: 0.61, GBP: 0.52, JPY: 98.00, CHF: 0.58, CAD: 0.89, AUD: 1.0 }
  };

  return {
    base: baseCurrency,
    rates: rates[baseCurrency] || rates.USD,
    timestamp: new Date().toISOString()
  };
};

const InvestmentTracker = () => {
  const [baseCurrency, setBaseCurrency] = useState('USD');
  const [fxRates, setFxRates] = useState(null);
  const [accounts, setAccounts] = useState([
    {
      id: '1',
      name: 'Main Brokerage',
      bank: 'Vanguard',
      type: 'Brokerage',
      currency: 'USD'
    }
  ]);

  const [holdings, setHoldings] = useState([
    {
      id: '1',
      accountId: '1',
      symbol: 'AAPL',
      name: 'Apple Inc.',
      type: 'Stock',
      quantity: 50,
      purchasePrice: 150.00,
      currentPrice: 180.00,
      currency: 'USD',
      dividendYield: 0.52,
      purchaseDate: '2023-06-15'
    },
    {
      id: '2',
      accountId: '1',
      symbol: 'VOO',
      name: 'Vanguard S&P 500 ETF',
      type: 'ETF',
      quantity: 25,
      purchasePrice: 380.00,
      currentPrice: 420.00,
      currency: 'USD',
      dividendYield: 1.45,
      purchaseDate: '2023-08-20'
    }
  ]);

  const [cashBalances, setCashBalances] = useState([
    {
      id: '1',
      accountId: '1',
      currency: 'EUR',
      amount: 10000.00
    },
    {
      id: '2',
      accountId: '1',
      currency: 'AUD',
      amount: 2000.00
    },
    {
      id: '3',
      accountId: '1',
      currency: 'USD',
      amount: 5000.00
    },
    {
      id: '4',
      accountId: '1',
      currency: 'JPY',
      amount: 500000.00
    }
  ]);

  const [showAddAccount, setShowAddAccount] = useState(false);
  const [showAddHolding, setShowAddHolding] = useState(false);
  const [showAddCash, setShowAddCash] = useState(false);
  const [selectedAccount, setSelectedAccount] = useState('all');

  useEffect(() => {
    loadFXRates();
  }, [baseCurrency]);

  const loadFXRates = async () => {
    const rates = await fetchFXRates(baseCurrency);
    setFxRates(rates);
  };

  const convertCurrency = (amount, fromCurrency, toCurrency) => {
    if (!fxRates || fromCurrency === toCurrency) return amount;
    const inBase = amount / fxRates.rates[fromCurrency];
    return inBase * fxRates.rates[toCurrency];
  };

  const calculateHoldingMetrics = (holding) => {
    const totalCost = holding.quantity * holding.purchasePrice;
    const currentValue = holding.quantity * holding.currentPrice;
    const gainLoss = currentValue - totalCost;
    const gainLossPercent = (gainLoss / totalCost) * 100;
    const annualDividend = currentValue * (holding.dividendYield / 100);

    return {
      totalCost,
      currentValue,
      gainLoss,
      gainLossPercent,
      annualDividend
    };
  };

  const getCashSummary = () => {
    const filteredCash = selectedAccount === 'all'
      ? cashBalances
      : cashBalances.filter(c => c.accountId === selectedAccount);

    // Group by currency
    const byCurrency = filteredCash.reduce((acc, cash) => {
      acc[cash.currency] = (acc[cash.currency] || 0) + cash.amount;
      return acc;
    }, {});

    // Calculate total in base currency
    let totalInBase = 0;
    Object.entries(byCurrency).forEach(([currency, amount]) => {
      totalInBase += convertCurrency(amount, currency, baseCurrency);
    });

    return { byCurrency, totalInBase };
  };

  const addCashBalance = (accountId, currency, amount) => {
    // Check if this currency already exists for this account
    const existing = cashBalances.find(
      c => c.accountId === accountId && c.currency === currency
    );

    if (existing) {
      // Update existing balance
      setCashBalances(
        cashBalances.map(c =>
          c.id === existing.id
            ? { ...c, amount: c.amount + amount }
            : c
        )
      );
    } else {
      // Add new cash balance
      setCashBalances([
        ...cashBalances,
        {
          id: Date.now().toString(),
          accountId,
          currency,
          amount
        }
      ]);
    }
    setShowAddCash(false);
  };

  const getPortfolioSummary = () => {
    const filteredHoldings = selectedAccount === 'all' 
      ? holdings 
      : holdings.filter(h => h.accountId === selectedAccount);

    let totalValue = 0;
    let totalCost = 0;
    let totalDividends = 0;

    filteredHoldings.forEach(holding => {
      const metrics = calculateHoldingMetrics(holding);
      totalValue += convertCurrency(metrics.currentValue, holding.currency, baseCurrency);
      totalCost += convertCurrency(metrics.totalCost, holding.currency, baseCurrency);
      totalDividends += convertCurrency(metrics.annualDividend, holding.currency, baseCurrency);
    });

    // Add cash to total value and cost
    const cashSummary = getCashSummary();
    totalValue += cashSummary.totalInBase;
    totalCost += cashSummary.totalInBase; // Cash cost basis equals its value

    const totalGainLoss = totalValue - totalCost;
    const totalGainLossPercent = totalCost > 0 ? (totalGainLoss / totalCost) * 100 : 0;

    return { totalValue, totalCost, totalGainLoss, totalGainLossPercent, totalDividends };
  };

  const addAccount = (newAccount) => {
    setAccounts([...accounts, { ...newAccount, id: Date.now().toString() }]);
    setShowAddAccount(false);
  };

  const addHolding = (newHolding) => {
    setHoldings([...holdings, { ...newHolding, id: Date.now().toString() }]);
    setShowAddHolding(false);
  };

  const summary = getPortfolioSummary();

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 p-4 md:p-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="bg-white rounded-xl shadow-lg p-6 mb-6">
          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
            <div>
              <h1 className="text-3xl font-bold text-slate-800 flex items-center gap-2">
                <BarChart3 className="w-8 h-8 text-blue-600" />
                Investment Portfolio Tracker
              </h1>
              <p className="text-slate-600 mt-1">Multi-currency portfolio management</p>
            </div>
            <div className="flex items-center gap-3">
              <select
                value={baseCurrency}
                onChange={(e) => setBaseCurrency(e.target.value)}
                className="px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              >
                {CURRENCIES.map(curr => (
                  <option key={curr} value={curr}>{curr}</option>
                ))}
              </select>
              <button
                onClick={loadFXRates}
                className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                title="Refresh FX Rates"
              >
                <RefreshCw className="w-5 h-5" />
              </button>
            </div>
          </div>
        </div>

        {/* Portfolio Summary Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
          <div className="bg-white rounded-xl shadow-md p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-slate-600 text-sm font-medium">Total Value</p>
                <p className="text-2xl font-bold text-slate-800 mt-1">
                  {baseCurrency} {summary.totalValue.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}
                </p>
              </div>
              <DollarSign className="w-10 h-10 text-blue-600 opacity-80" />
            </div>
          </div>

          <div className="bg-white rounded-xl shadow-md p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-slate-600 text-sm font-medium">Total Cost</p>
                <p className="text-2xl font-bold text-slate-800 mt-1">
                  {baseCurrency} {summary.totalCost.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}
                </p>
              </div>
              <Wallet className="w-10 h-10 text-slate-600 opacity-80" />
            </div>
          </div>

          <div className="bg-white rounded-xl shadow-md p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-slate-600 text-sm font-medium">Gain/Loss</p>
                <p className={`text-2xl font-bold mt-1 ${summary.totalGainLoss >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                  {summary.totalGainLoss >= 0 ? '+' : ''}{baseCurrency} {summary.totalGainLoss.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}
                </p>
                <p className={`text-sm font-medium ${summary.totalGainLoss >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                  {summary.totalGainLoss >= 0 ? '+' : ''}{summary.totalGainLossPercent.toFixed(2)}%
                </p>
              </div>
              {summary.totalGainLoss >= 0 ? 
                <TrendingUp className="w-10 h-10 text-green-600 opacity-80" /> : 
                <TrendingDown className="w-10 h-10 text-red-600 opacity-80" />
              }
            </div>
          </div>

          <div className="bg-white rounded-xl shadow-md p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-slate-600 text-sm font-medium">Annual Dividends</p>
                <p className="text-2xl font-bold text-green-600 mt-1">
                  {baseCurrency} {summary.totalDividends.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}
                </p>
              </div>
              <TrendingUp className="w-10 h-10 text-green-600 opacity-80" />
            </div>
          </div>
        </div>

        {/* Cash Balances Section */}
        <div className="bg-white rounded-xl shadow-lg p-6 mb-6">
          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-4">
            <div>
              <h2 className="text-xl font-bold text-slate-800">Cash Balances</h2>
              <p className="text-sm text-slate-600 mt-1">
                Total in {baseCurrency}: {getCashSummary().totalInBase.toLocaleString(undefined, {minimumFractionDigits: 2, maximumFractionDigits: 2})}
                {' • '}
                {Object.keys(getCashSummary().byCurrency).length} {Object.keys(getCashSummary().byCurrency).length === 1 ? 'currency' : 'currencies'}
              </p>
            </div>
            <button
              onClick={() => setShowAddCash(true)}
              className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors"
            >
              <PlusCircle className="w-5 h-5" />
              Deposit/Withdraw
            </button>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">{Object.entries(getCashSummary().byCurrency).map(([currency, amount]) => {
              const valueInBase = convertCurrency(amount, currency, baseCurrency);
              return (
                <div key={currency} className="bg-gradient-to-br from-slate-50 to-slate-100 rounded-lg p-4 border border-slate-200">
                  <div className="flex items-center gap-2 mb-2">
                    <DollarSign className="w-5 h-5 text-slate-600" />
                    <span className="text-sm font-semibold text-slate-600">{currency}</span>
                  </div>
                  <p className="text-2xl font-bold text-slate-800">{amount.toLocaleString(undefined, {minimumFractionDigits: 2})}</p>
                  <p className="text-xs text-slate-500 mt-1">
                    ≈ {baseCurrency} {valueInBase.toLocaleString(undefined, {minimumFractionDigits: 2})}
                  </p>
                </div>
              );
            })}
            {Object.keys(getCashSummary().byCurrency).length === 0 && (
              <div className="col-span-full text-center py-8 text-slate-500">
                No cash balances yet. Click "Deposit/Withdraw" to add funds.
              </div>
            )}
          </div>
        </div>

        {/* Accounts and Filter */}
        <div className="bg-white rounded-xl shadow-lg p-6 mb-6">
          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-4">
            <h2 className="text-xl font-bold text-slate-800">Accounts</h2>
            <button
              onClick={() => setShowAddAccount(true)}
              className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
            >
              <PlusCircle className="w-5 h-5" />
              Add Account
            </button>
          </div>

          <div className="flex flex-wrap gap-2">
            <button
              onClick={() => setSelectedAccount('all')}
              className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                selectedAccount === 'all' 
                  ? 'bg-blue-600 text-white' 
                  : 'bg-slate-100 text-slate-700 hover:bg-slate-200'
              }`}
            >
              All Accounts
            </button>
            {accounts.map(account => (
              <button
                key={account.id}
                onClick={() => setSelectedAccount(account.id)}
                className={`px-4 py-2 rounded-lg font-medium transition-colors ${
                  selectedAccount === account.id 
                    ? 'bg-blue-600 text-white' 
                    : 'bg-slate-100 text-slate-700 hover:bg-slate-200'
                }`}
              >
                {account.name} ({account.currency})
              </button>
            ))}
          </div>
        </div>

        {/* Holdings Table */}
        <div className="bg-white rounded-xl shadow-lg p-6">
          <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-6">
            <h2 className="text-xl font-bold text-slate-800">Holdings</h2>
            <button
              onClick={() => setShowAddHolding(true)}
              className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors"
            >
              <PlusCircle className="w-5 h-5" />
              Add Holding
            </button>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full">
              <thead>
                <tr className="border-b border-slate-200">
                  <th className="text-left py-3 px-4 text-slate-600 font-semibold">Symbol</th>
                  <th className="text-left py-3 px-4 text-slate-600 font-semibold">Name</th>
                  <th className="text-left py-3 px-4 text-slate-600 font-semibold">Type</th>
                  <th className="text-right py-3 px-4 text-slate-600 font-semibold">Quantity</th>
                  <th className="text-right py-3 px-4 text-slate-600 font-semibold">Avg Cost</th>
                  <th className="text-right py-3 px-4 text-slate-600 font-semibold">Current Price</th>
                  <th className="text-right py-3 px-4 text-slate-600 font-semibold">Total Value</th>
                  <th className="text-right py-3 px-4 text-slate-600 font-semibold">Gain/Loss</th>
                  <th className="text-right py-3 px-4 text-slate-600 font-semibold">Dividend Yield</th>
                </tr>
              </thead>
              <tbody>
                {holdings
                  .filter(h => selectedAccount === 'all' || h.accountId === selectedAccount)
                  .map(holding => {
                    const metrics = calculateHoldingMetrics(holding);
                    return (
                      <tr key={holding.id} className="border-b border-slate-100 hover:bg-slate-50 transition-colors">
                        <td className="py-4 px-4 font-semibold text-slate-800">{holding.symbol}</td>
                        <td className="py-4 px-4 text-slate-600">{holding.name}</td>
                        <td className="py-4 px-4">
                          <span className="px-2 py-1 bg-blue-100 text-blue-700 rounded-md text-sm font-medium">
                            {holding.type}
                          </span>
                        </td>
                        <td className="py-4 px-4 text-right text-slate-800">{holding.quantity}</td>
                        <td className="py-4 px-4 text-right text-slate-800">
                          {holding.currency} {holding.purchasePrice.toFixed(2)}
                        </td>
                        <td className="py-4 px-4 text-right text-slate-800">
                          {holding.currency} {holding.currentPrice.toFixed(2)}
                        </td>
                        <td className="py-4 px-4 text-right font-semibold text-slate-800">
                          {holding.currency} {metrics.currentValue.toLocaleString(undefined, {minimumFractionDigits: 2})}
                        </td>
                        <td className="py-4 px-4 text-right">
                          <div className={`font-semibold ${metrics.gainLoss >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                            {metrics.gainLoss >= 0 ? '+' : ''}{holding.currency} {metrics.gainLoss.toFixed(2)}
                          </div>
                          <div className={`text-sm ${metrics.gainLoss >= 0 ? 'text-green-600' : 'text-red-600'}`}>
                            {metrics.gainLoss >= 0 ? '+' : ''}{metrics.gainLossPercent.toFixed(2)}%
                          </div>
                        </td>
                        <td className="py-4 px-4 text-right">
                          <div className="text-slate-800 font-medium">{holding.dividendYield.toFixed(2)}%</div>
                          <div className="text-sm text-slate-600">
                            {holding.currency} {metrics.annualDividend.toFixed(2)}/yr
                          </div>
                        </td>
                      </tr>
                    );
                  })}
              </tbody>
            </table>
          </div>
        </div>

        {/* Add Account Modal */}
        {showAddAccount && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
            <div className="bg-white rounded-xl shadow-2xl p-6 max-w-md w-full">
              <h3 className="text-xl font-bold text-slate-800 mb-4">Add New Account</h3>
              <form onSubmit={(e) => {
                e.preventDefault();
                const formData = new FormData(e.target);
                addAccount({
                  name: formData.get('name'),
                  bank: formData.get('bank'),
                  type: formData.get('type'),
                  currency: formData.get('currency')
                });
              }}>
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Account Name</label>
                    <input name="name" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Bank/Institution</label>
                    <input name="bank" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Account Type</label>
                    <select name="type" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent">
                      {ACCOUNT_TYPES.map(type => <option key={type} value={type}>{type}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Currency</label>
                    <select name="currency" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent">
                      {CURRENCIES.map(curr => <option key={curr} value={curr}>{curr}</option>)}
                    </select>
                  </div>
                </div>
                <div className="flex gap-3 mt-6">
                  <button type="button" onClick={() => setShowAddAccount(false)} className="flex-1 px-4 py-2 border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 transition-colors">
                    Cancel
                  </button>
                  <button type="submit" className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors">
                    Add Account
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

        {/* Add Holding Modal */}
        {showAddHolding && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
            <div className="bg-white rounded-xl shadow-2xl p-6 max-w-md w-full max-h-[90vh] overflow-y-auto">
              <h3 className="text-xl font-bold text-slate-800 mb-4">Add New Holding</h3>
              <form onSubmit={(e) => {
                e.preventDefault();
                const formData = new FormData(e.target);
                addHolding({
                  accountId: formData.get('accountId'),
                  symbol: formData.get('symbol'),
                  name: formData.get('name'),
                  type: formData.get('type'),
                  quantity: parseFloat(formData.get('quantity')),
                  purchasePrice: parseFloat(formData.get('purchasePrice')),
                  currentPrice: parseFloat(formData.get('currentPrice')),
                  currency: formData.get('currency'),
                  dividendYield: parseFloat(formData.get('dividendYield') || 0),
                  purchaseDate: formData.get('purchaseDate')
                });
              }}>
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Account</label>
                    <select name="accountId" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent">
                      {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name} - {acc.bank}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Symbol/Ticker</label>
                    <input name="symbol" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" placeholder="AAPL" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Name</label>
                    <input name="name" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" placeholder="Apple Inc." />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Asset Type</label>
                    <select name="type" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent">
                      {ASSET_TYPES.map(type => <option key={type} value={type}>{type}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Quantity</label>
                    <input name="quantity" type="number" step="0.001" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Purchase Price</label>
                    <input name="purchasePrice" type="number" step="0.01" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Current Price</label>
                    <input name="currentPrice" type="number" step="0.01" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Currency</label>
                    <select name="currency" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent">
                      {CURRENCIES.map(curr => <option key={curr} value={curr}>{curr}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Dividend Yield (%)</label>
                    <input name="dividendYield" type="number" step="0.01" className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" placeholder="0.00" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Purchase Date</label>
                    <input name="purchaseDate" type="date" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" />
                  </div>
                </div>
                <div className="flex gap-3 mt-6">
                  <button type="button" onClick={() => setShowAddHolding(false)} className="flex-1 px-4 py-2 border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 transition-colors">
                    Cancel
                  </button>
                  <button type="submit" className="flex-1 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors">
                    Add Holding
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

        {/* Add Cash Modal */}
        {showAddCash && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
            <div className="bg-white rounded-xl shadow-2xl p-6 max-w-md w-full">
              <h3 className="text-xl font-bold text-slate-800 mb-4">Deposit / Withdraw Cash</h3>
              <form onSubmit={(e) => {
                e.preventDefault();
                const formData = new FormData(e.target);
                const amount = parseFloat(formData.get('amount'));
                const transactionType = formData.get('transactionType');
                const finalAmount = transactionType === 'withdraw' ? -amount : amount;

                addCashBalance(
                  formData.get('accountId'),
                  formData.get('currency'),
                  finalAmount
                );
              }}>
                <div className="space-y-4">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Transaction Type</label>
                    <select name="transactionType" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-transparent">
                      <option value="deposit">Deposit</option>
                      <option value="withdraw">Withdraw</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Account</label>
                    <select name="accountId" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-transparent">
                      {accounts.map(acc => <option key={acc.id} value={acc.id}>{acc.name} - {acc.bank}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Currency</label>
                    <select name="currency" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-transparent">
                      {CURRENCIES.map(curr => <option key={curr} value={curr}>{curr}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Amount</label>
                    <input 
                      name="amount" 
                      type="number" 
                      step="0.01" 
                      min="0.01"
                      required 
                      className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-transparent" 
                      placeholder="0.00"
                    />
                  </div>
                  <div className="bg-blue-50 border border-blue-200 rounded-lg p-3">
                    <p className="text-sm text-blue-800">
                      <strong>Note:</strong> The amount will be added to or subtracted from your existing balance in this currency.
                    </p>
                  </div>
                </div>
                <div className="flex gap-3 mt-6">
                  <button type="button" onClick={() => setShowAddCash(false)} className="flex-1 px-4 py-2 border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 transition-colors">
                    Cancel
                  </button>
                  <button type="submit" className="flex-1 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors">
                    Confirm
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default InvestmentTracker;

