import express from 'express';
import pool from '../db/connection.js';

const router = express.Router();

// GET all accounts
router.get('/', async (req, res, next) => {
  try {
    const result = await pool.query(
      'SELECT * FROM accounts ORDER BY created_at DESC'
    );
    res.json(result.rows);
  } catch (error) {
    next(error);
  }
});

// POST create account
router.post('/', async (req, res, next) => {
  try {
    const { name, bank, type, currency } = req.body;

    if (!name || !bank || !type || !currency) {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    const result = await pool.query(
      'INSERT INTO accounts (name, bank, type, currency) VALUES ($1, $2, $3, $4) RETURNING *',
      [name, bank, type, currency]
    );

    res.status(201).json(result.rows[0]);
  } catch (error) {
    next(error);
  }
});

// PUT update account
router.put('/:id', async (req, res, next) => {
  try {
    const { id } = req.params;
    const { name, bank, type, currency } = req.body;

    const result = await pool.query(
      'UPDATE accounts SET name = $1, bank = $2, type = $3, currency = $4 WHERE id = $5 RETURNING *',
      [name, bank, type, currency, id]
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Account not found' });
    }

    res.json(result.rows[0]);
  } catch (error) {
    next(error);
  }
});

// DELETE account
router.delete('/:id', async (req, res, next) => {
  try {
    const { id } = req.params;

    const result = await pool.query(
      'DELETE FROM accounts WHERE id = $1 RETURNING *',
      [id]
    );

    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Account not found' });
    }

    res.json({ message: 'Account deleted successfully' });
  } catch (error) {
    next(error);
  }
});

export default router;

import React from 'react';
import { ACCOUNT_TYPES, CURRENCIES } from '../utils/constants';

const AddAccountModal = ({ showAddAccount, setShowAddAccount, addAccount }) => {
  if (!showAddAccount) return null;

  const handleSubmit = (e) => {
    e.preventDefault();
    const formData = new FormData(e.target);
    addAccount({
      name: formData.get('name'),
      bank: formData.get('bank'),
      type: formData.get('type'),
      currency: formData.get('currency')
    });
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
      <div className="bg-white rounded-xl shadow-2xl p-6 max-w-md w-full">
        <h3 className="text-xl font-bold text-slate-800 mb-4">Add New Account</h3>
        <form onSubmit={handleSubmit}>
          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Account Name</label>
              <input name="name" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Bank/Institution</label>
              <input name="bank" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent" />
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Account Type</label>
              <select name="type" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent">
                {ACCOUNT_TYPES.map(type => <option key={type} value={type}>{type}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Currency</label>
              <select name="currency" required className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent">
                {CURRENCIES.map(curr => <option key={curr} value={curr}>{curr}</option>)}
              </select>
            </div>
          </div>
          <div className="flex gap-3 mt-6">
            <button type="button" onClick={() => setShowAddAccount(false)} className="flex-1 px-4 py-2 border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 transition-colors">
              Cancel
            </button>
            <button type="submit" className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors">
              Add Account
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default AddAccountModal;

import React from 'react';
import { PlusCircle } from 'lucide-react';

const AccountFilter = ({ accounts, selectedAccount, setSelectedAccount, setShowAddAccount }) => {
  return (
    <div className="bg-white rounded-xl shadow-lg p-6 mb-6">
      <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4 mb-4">
        <h2 className="text-xl font-bold text-slate-800">Accounts</h2>
        <button
          onClick={() => setShowAddAccount(true)}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
        >
          <PlusCircle className="w-5 h-5" />
          Add Account
        </button>
      </div>

      <div className="flex flex-wrap gap-2">
        <button
          onClick={() => setSelectedAccount('all')}
          className={`px-4 py-2 rounded-lg font-medium transition-colors ${
            selectedAccount === 'all'
              ? 'bg-blue-600 text-white'
              : 'bg-slate-100 text-slate-700 hover:bg-slate-200'
          }`}
        >
          All Accounts
        </button>
        {accounts.map(account => (
          <button
            key={account.id}
            onClick={() => setSelectedAccount(account.id)}
            className={`px-4 py-2 rounded-lg font-medium transition-colors ${
              selectedAccount == account.id
                ? 'bg-blue-600 text-white'
                : 'bg-slate-100 text-slate-700 hover:bg-slate-200'
            }`}
          >
            {account.name} ({account.currency})
          </button>
        ))}
      </div>
    </div>
  );
};

export default AccountFilter;

