    try {
      const rates = await api.getFXRates(baseCurrency);
      setFxRates(rates);
    } catch (error) {
      console.error('Failed to load FX rates:', error);
    }
  };

  const loadAccounts = async () => {
    try {
      const data = await api.getAccounts();
      setAccounts(data);
