import express from 'express';

const router = express.Router();

// In-memory cache for FX rates
const cache = {
  data: {},
  timestamp: null
};

// Cache duration: 1 hour (rates update daily, but we cache for 1 hour to allow manual refresh)
const CACHE_DURATION = 60 * 60 * 1000; // 1 hour in milliseconds

// Mock FX Rate data as fallback
const mockRates = {
  USD: { USD: 1.0, EUR: 0.92, GBP: 0.79, JPY: 149.50, CHF: 0.88, CAD: 1.36, AUD: 1.52, BRL: 5.0, INR: 83.0, NZD: 1.65, TRY: 32.0 },
