        <div className="flex justify-end mt-6">
          <button
            onClick={() => setShowFXRates(false)}
            className="px-4 py-2 bg-slate-600 text-white rounded-lg hover:bg-slate-700 transition-colors"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
};

export default FXRatesModal;
